  $('#view-payment').innerHTML=`<div class="page-head"><div><h1>تسجيل دفعة</h1><p>مسار مختصر وواضح: اختيار الطالب ← القسط/الرصيد ← المبلغ وسعر الصرف ← الحفظ.</p></div></div>${studentPicker('payment')}${quickLinksBar()}<div class="card"><div class="card-head"><h3>بيانات الدفع</h3></div><div class="card-body">${selectedInfo}${summaryStrip}${!f?'<div class="notice" style="margin-top:12px">لا يوجد ملف مالي لهذا الطالب. يجب إنشاء الرسوم والخطة أولاً.</div>':`<div class="finance-form" style="margin-top:14px"><div class="finance-section-title"><b>1) نوع العملية</b><small>اختاري هل هي دفعة كاملة أم لقسط محدد</small></div><div class="field span-3"><label>طريقة التطبيق</label><select id="paymentPlanMode" class="select" onchange="FinancePro.setPaymentPlanMode()"><option value="full">دفع كامل للرصيد</option><option value="installment">دفع قسط محدد</option></select></div><div class="field span-5"><label>القسط</label><select id="payInstall" class="select" onchange="FinancePro.fillPaymentAmountFromSelection()">${installmentOptions}</select></div><div class="field span-4"><label>تاريخ الدفع</label><input id="payDate" class="input" type="date" value="${iso()}"></div>${installmentNotice}<div class="finance-section-title"><b>2) المبلغ وسعر الصرف</b><small>هذا القسم هو الوحيد الخاص بسعر الصرف</small></div><div class="field span-3"><label>العملة المدفوعة</label><select id="payCurrency" class="select" onchange="FinancePro.updateCurrencyUI()"><option value="USD">دولار أمريكي</option><option value="IRR">ريال إيراني</option></select></div><div class="field span-3"><label id="payAmountLabel">المبلغ بالدولار</label><input id="payAmount" class="input" type="number" step="0.01" oninput="FinancePro.updateUsdPreview()"></div><div class="field span-3"><label>سعر الصرف USD/IRR</label><input id="payRate" class="input" type="number" value="${esc(rate)}" oninput="FinancePro.updateUsdPreview()"></div><div class="field span-3"><label>&nbsp;</label><button type="button" class="btn blue block" onclick="FinancePro.fetchTgjuRate()">جلب من TGJU + مصادر إيرانية</button></div><div class="span-12"><div id="ratePanel" class="calc-box"></div></div><div class="finance-section-title"><b>3) الدفع والاستلام</b><small>المعلومات الأساسية المطلوبة للحفظ</small></div><div class="field span-3"><label>طريقة الدفع</label><select id="payMethod" class="select" onchange="FinancePro.toggleTransfer()"><option value="cash">نقداً</option><option value="card">بطاقة مصرفية</option><option value="transfer">حوالة مصرفية</option><option value="other">أخرى</option></select></div><div class="field span-4"><label>اسم الدافع</label><input id="payerName" class="input" value="${esc(parentName(s.parent_id))}"></div><div class="field span-2"><label>صفة الدافع</label><input id="payerRel" class="input" value="ولي الأمر"></div><div class="field span-3"><label>المستلم الرسمي</label><select id="receivedBy" class="select" onchange="FinancePro.toggleReceiverName()">${receiverOptions()}</select></div><div class="field span-4" id="receiverNameBox" style="display:none"><label>اسم المستلم اليدوي</label><input id="receiverName" class="input" placeholder="مثال: المدير / المحاسب"></div><details class="finance-optional"><summary>تفاصيل إضافية اختيارية</summary><div class="finance-form" style="margin-top:12px"><div class="field span-4 transfer-fields" style="display:none"><label>رقم الحوالة</label><input id="transferNo" class="input"></div><div class="field span-4 transfer-fields" style="display:none"><label>تاريخ الحوالة</label><input id="transferDate" class="input" type="date"></div><div class="field span-4 transfer-fields" style="display:none"><label>الجهة المحولة</label><input id="transferSource" class="input"></div><div class="field span-6"><label>ملاحظات</label><input id="payNote" class="input" placeholder="أي ملاحظة داخلية أو وصف مختصر"></div><div class="field span-6"><label>صورة السند أو الإيصال 📎</label><div class="upload-box" style="padding:4px;border:1px dashed #ccc;border-radius:6px"><input type="file" id="payReceiptPhoto" accept="image/*,application/pdf"><div style="font-size:11px;color:#666">إرفاق صورة الإيصال (JPG/PNG/PDF)</div></div></div><div class="span-12 compact-note">هذه التفاصيل اختيارية، وتظهر فقط عند الحاجة لتوثيق إضافي.</div></div></details><div class="span-12"><button class="btn gold" onclick="FinancePro.savePayment()">حفظ الدفعة وإصدار إيصال</button></div></div>`}</div></div>`;
  setTimeout(()=>{setPaymentPlanMode();updateCurrencyUI();toggleReceiverName();},0);
