function setPaymentPlanMode(){
  const mode=$('#paymentPlanMode')?.value||'full';
  const select=$('#payInstall');
  if(select) select.disabled=mode==='full';
  fillPaymentAmountFromSelection();
}
function fillPaymentAmountFromSelection(){
  const f=SELECTED&&feeOf(SELECTED.id); if(!f||!$('#payAmount'))return;
  let usd=feeRemaining(f);
  if(($('#paymentPlanMode')?.value)==='installment'){
    const selected=$('#payInstall')?.value;
    if(selected==='__balance__') usd=feeRemaining(f);
    else {
      const inst=DATA.installments.find(i=>String(i.id)===String(selected));
      usd=inst?Math.max(num(inst.amount_due)-num(inst.amount_paid),0):0;
    }
  }
  if($('#payCurrency')?.value==='IRR'){
    const rate=num($('#payRate')?.value); $('#payAmount').value=rate?Math.round(usd*rate):'';
  }else $('#payAmount').value=usd.toFixed(2);
  updateUsdPreview();
}
function updateCurrencyUI(){
  const cur=$('#payCurrency')?.value||'USD';
  if($('#payAmountLabel')) $('#payAmountLabel').textContent=cur==='IRR'?'المبلغ بالريال الإيراني':'المبلغ بالدولار';
  fillPaymentAmountFromSelection();
}
function updateUsdPreview(){
  const cur=$('#payCurrency')?.value||'USD', amount=num($('#payAmount')?.value), rate=num($('#payRate')?.value);
  const usd=cur==='IRR'?(rate?amount/rate:0):amount;
  const panel=$('#ratePanel'); if(!panel)return;
  panel.innerHTML=`<div class="calc-row"><span>المبلغ المحتسب بالدولار</span><b>${money(usd)}</b></div><div class="calc-row"><span>سعر الصرف المستخدم</span><b>${rate?irr(rate):'0 — أدخلي السعر يدوياً'}</b></div><div class="calc-row"><span>المصدر</span><b>${esc((LIVE_RATE&&LIVE_RATE.source_label)|| (LIVE_RATE&&LIVE_RATE.source) || 'يدوي / آخر سعر محفوظ')}</b></div>${LIVE_RATE&&LIVE_RATE.sources_checked?`<div class="calc-row"><span>عدد المصادر المقروءة</span><b>${esc(String(LIVE_RATE.sources_checked))}</b></div>`:''}`;
}
async function fetchTgjuRate(){
  const btn=document.activeElement; if(btn)btn.disabled=true;
  try{
    if($('#payRate')) $('#payRate').value='0';
    LIVE_RATE=null;
    updateUsdPreview();
    const r=await fetch('/api/exchange/tgju',{cache:'no-store'});
    const d=await r.json();
    if(!d.ok) throw new Error(d.error||'تعذر جلب السعر');
    LIVE_RATE=d;
    if($('#payRate')) $('#payRate').value=d.rate;
    try{ await client().from('exchange_rates').insert({rate:d.rate,source:(d.source||'multi_iran'),source_url:d.url||null,is_manual:false,created_by:ME.id,notes:'TGJU + Iranian market sources auto fetch'}); }catch(_){ /* ignore archive failure */ }
    toast('تم جلب سعر الصرف',`${esc(d.source_label||d.source||'TGJU + مصادر إيرانية')}: ${irr(d.rate)}`,'green');
    updateUsdPreview();
  }catch(e){
    const archived=(DATA&&DATA.rates&&DATA.rates[0])?DATA.rates[0]:null;
    if(archived&&num(archived.rate)>0){
      LIVE_RATE={rate:num(archived.rate),source:archived.source||'archived',source_label:'آخر سعر محفوظ',sources_checked:0};
      if($('#payRate')) $('#payRate').value=String(num(archived.rate));
      updateUsdPreview();
      toast('تعذر الجلب المباشر','تم استخدام آخر سعر محفوظ مؤقتاً ('+irr(archived.rate)+'). تحققي منه قبل الحفظ. '+e.message,'gold');
    }else{
      LIVE_RATE={rate:0,source:'غير متوفر',source_label:'تعذر الوصول إلى TGJU والمصادر الإيرانية'};
      if($('#payRate')) $('#payRate').value='0';
      updateUsdPreview();
      toast('تعذر جلب السعر','تعذر الوصول إلى TGJU والمصادر الإيرانية. تم وضع سعر الصرف = 0 لمنع استخدام سعر قديم. أدخلي السعر يدوياً. '+e.message,'red');
    }
  }finally{if(btn)btn.disabled=false}
}
function toggleTransfer(){$$('.transfer-fields').forEach(x=>x.style.display=$('#payMethod').value==='transfer'?'block':'none')}function toggleReceiverName(){const manual=$('#receivedBy')?.value==='__other__';const box=$('#receiverNameBox');if(box)box.style.display=manual?'block':'none'}function toggleCurrency(){}
async function savePayment(){
  if(!SELECTED)return;
  const f=feeOf(SELECTED.id);
  if(!f){toast('تنبيه','لا يوجد ملف مالي لهذا الطالب','red');return}
  const mode=$('#paymentPlanMode')?.value||'full';
  const iid=mode==='installment'?$('#payInstall')?.value:null;
  const directBalance = iid==='__balance__';
  const inst=(iid && !directBalance)?DATA.installments.find(i=>String(i.id)===String(iid)):null;
  if(mode==='installment'&&!inst&&!directBalance){toast('تنبيه','لا يوجد قسط مفتوح لهذا الطالب. يمكنك اختيار دفع كامل أو إنشاء خطة أقساط أولاً.','red');return}
  let amount=num($('#payAmount').value),currency=$('#payCurrency').value,rate=num($('#payRate').value),usd=amount,irrAmount=null;
  if(currency==='IRR'){
    irrAmount=amount;
    if(!rate){toast('سعر الصرف مطلوب','أدخلي سعر الدولار مقابل الريال','red');return}
    usd=Math.round((amount/rate)*100)/100;
  }
  if(!usd||usd<=0){toast('تنبيه','أدخلي مبلغاً صحيحاً','red');return}
  const maxAllowed = mode==='installment' ? (inst?Math.max(num(inst.amount_due)-num(inst.amount_paid),0):feeRemaining(f)) : feeRemaining(f);
  if(usd > maxAllowed + 0.01){toast('مبلغ زائد',maxAllowed<=0?'لا يوجد مبلغ مستحق حالياً على هذا الملف. الرصيد الدائن: '+money(feeCredit(f)):'المبلغ المدفوع أكبر من الرصيد المسموح. الحد الأعلى هو '+money(maxAllowed),'red');return}
  const receipt='RC-'+Date.now();
  const receiverId=$('#receivedBy')?.value||ME.id;
  const receiverUser=receiverId&&receiverId!=='__other__'?DATA.userMap.get(String(receiverId)):null;
  const receiverManual=$('#receiverName')?.value||'';
  const receiverFullName=receiverId==='__other__'?(receiverManual||'مستلم يدوي'):(receiverUser&&(receiverUser.name||receiverUser.email)||ME.name||ME.email||'—');
  try{
    let attUrl = null;
    const photoEl = $('#payReceiptPhoto');
    const photoFile = photoEl && photoEl.files && photoEl.files[0];
    if (photoFile) {
      const ext = (photoFile.name.split('.').pop() || 'jpg').toLowerCase();
      const path = `payments/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
      const { error: photoErr } = await client().storage.from('finance-receipts').upload(path, photoFile, { upsert: false, contentType: photoFile.type || 'image/jpeg' });
      if (photoErr) console.warn('Payment receipt upload failed:', photoErr);
      else attUrl = path;
    }
    const payload={student_fee_id:f.id,attachment_url:attUrl,student_installment_id:(directBalance?null:(iid||null)),amount:usd,amount_usd:usd,amount_irr:irrAmount,currency,payment_date:$('#payDate').value,payment_method:$('#payMethod').value,exchange_rate_value:rate||null,transfer_number:$('#transferNo').value||null,transfer_date:$('#transferDate').value||null,transfer_source:$('#transferSource').value||null,payer_name:$('#payerName').value||parentName(SELECTED.parent_id),payer_relationship:$('#payerRel').value||'ولي الأمر',received_by:receiverId==='__other__'?null:receiverId,receiver_name:receiverFullName,receiver_role:receiverUser&&receiverUser.role||null,note:$('#payNote').value||null,receipt_number:receipt,created_by:ME.id,created_by_name:ME.name};
    const {error}=await client().from('fee_payments').insert(payload);if(error)throw error;
    if(mode==='installment' && inst){
      const newPaid=num(inst.amount_paid)+usd,newStatus=newPaid>=num(inst.amount_due)?'paid':'partial';
      await client().from('student_installments').update({amount_paid:newPaid,actual_payment_date:$('#payDate').value,balance_remaining:Math.max(num(inst.amount_due)-newPaid,0),status:newStatus}).eq('id',iid);
    }else if(mode==='installment' && directBalance){
      // لا توجد أقساط محفوظة: تسجل الدفعة على رصيد الملف المالي فقط.
    }else{
      const open=installmentsOf(f.id).filter(i=>Math.max(num(i.amount_due)-num(i.amount_paid),0)>0);
      for(const i of open){await client().from('student_installments').update({amount_paid:num(i.amount_due),actual_payment_date:$('#payDate').value,balance_remaining:0,status:'paid'}).eq('id',i.id)}
    }
    const feePaid=num(f.total_paid)+usd,feeStatus=feePaid>=num(f.net_amount)?'paid':'partial';
    await client().from('student_fees').update({total_paid:feePaid,status:feeStatus,updated_by:ME.id}).eq('id',f.id);
    toast('تم حفظ الدفعة','رقم الإيصال: '+receipt,'green');
    renderReceipt(SELECTED,payload,inst||{installment_number:(directBalance?'دفعة على الرصيد':'دفع كامل')});
    await load();
  }catch(e){queueOffline({type:'payment',student_id:SELECTED.id,installment_id:iid,amount,currency,date:$('#payDate').value});toast('تعذر حفظ الدفعة','تم حفظ العملية كمسودة طوارئ Offline: '+e.message,'red')}
}
function renderReceipt(s,p,inst){
  const f=feeOf(s.id);
  const remaining=Math.max(num(f&&f.net_amount)-num(f&&f.total_paid)-num(p.amount_usd),0);
  const typeLabel=receiptPaymentLabel(inst,p);
  const methodLabel=paymentMethodLabel(p.payment_method);
  const receiverLabel=receiverName(p);
  const payerLabel=payerDisplay(p);
  const meta=solarParts(p.payment_date);
  const periodLabel=meta?`${meta.monthName||solarMonthNameFromDate(p.payment_date)} ${meta.year}`:'—';
  $('#view-payment').insertAdjacentHTML('beforeend',`<div class="receipt"><div class="receipt-head"><div><h2>إيصال دفع رسمي</h2><p>رقم الإيصال: ${esc(p.receipt_number)}<br>التاريخ: ${esc(dualDate(p.payment_date))}<br>الفترة الشمسية: ${esc(periodLabel)}</p></div><div class="receipt-logo">ع</div></div><div class="receipt-summary"><div class="finance-summary-item"><small>المبلغ المقبوض</small><b>${esc(dualMoney(p.amount_usd,p.amount_irr))}</b></div><div class="finance-summary-item"><small>المتبقي بعد العملية</small><b>${esc(dualMoney(remaining))}</b></div><div class="finance-summary-item"><small>الرصيد الدائن</small><b>${esc(dualMoney(feeCredit(f)))} </b></div><div class="finance-summary-item"><small>المستلم</small><b>${esc(receiverLabel)}</b></div></div><table class="receipt-table"><tbody><tr><th>الطالب</th><td>${esc(fullName(s))}</td><th>الصف</th><td>${esc(className(s.class_id))}</td></tr><tr><th>ولي الأمر</th><td>${esc(parentName(s.parent_id))}</td><th>الدافع</th><td>${esc(payerLabel)}</td></tr><tr><th>نوع الدفعة</th><td>${esc(typeLabel)}</td><th>طريقة الدفع</th><td>${esc(methodLabel)}</td></tr><tr><th>المبلغ</th><td><b>${dualMoney(p.amount_usd,p.amount_irr)}</b></td><th>سعر الصرف</th><td>${p.exchange_rate_value?irr(p.exchange_rate_value):'—'}</td></tr><tr><th>الرصيد المتبقي بعد العملية</th><td>${dualMoney(remaining)}</td><th>الرصيد الدائن</th><td>${dualMoney(feeCredit(f))}</td></tr><tr><th>حالة الملف</th><td>${esc((f&&f.status)||'—')}</td><th>المستلم الرسمي</th><td>${esc(receiverLabel)}</td></tr><tr><th>رقم الحوالة</th><td>${esc(p.transfer_number||'—')}</td><th>ملاحظات</th><td>${esc(p.note||'—')}</td></tr></tbody></table>${p.attachment_url?`<div style="margin-top:12px"><a class="btn blue" href="/api/proxy/storage/v1/object/public/finance-receipts/${p.attachment_url}" target="_blank">فتح صورة السند / الإيصال</a></div>`:''}<div class="receipt-actions no-print"><button class="btn gold" onclick="window.print()">طباعة الإيصال</button><button class="btn blue" onclick="FinancePro.render('payment')">تسجيل دفعة أخرى</button><button class="btn" onclick="FinancePro.render('students')">فتح كشف الطالب</button></div><div class="receipt-foot"><span>توقيع المحاسب</span><span>ختم المدرسة</span><span>توقيع ولي الأمر</span></div></div>`)
}
function renderInstallments(){const rowsData=DATA.installments.map((i,n)=>{const f=DATA.fees.find(x=>String(x.id)===String(i.student_fee_id)),s=f&&DATA.studentMap.get(String(f.student_id)),st=installmentStatus(i),remain=Math.max(num(i.amount_due)-num(i.amount_paid),0),sev=overdueSeverity(i);return{student:s,installment:i,index:n,status:st,remain,severity:sev}});const overdue=rowsData.filter(r=>r.status==='متأخر');const partial=rowsData.filter(r=>r.status==='مدفوع جزئياً');const open=rowsData.filter(r=>r.status!=='مدفوع');const rows=rowsData.map(r=>`<tr><td>${esc(r.student?fullName(r.student):'—')}</td><td>${esc(r.student?className(r.student.class_id):'—')}</td><td>${r.installment.installment_number||r.index+1}</td><td>${esc(r.installment.due_date?dualDate(r.installment.due_date):'—')}</td><td>${dualMoney(r.installment.amount_due)}</td><td>${dualMoney(r.installment.amount_paid)}</td><td>${dualMoney(r.remain)}</td><td><span class="badge ${statusClass(r.status)}">${r.status}</span></td><td>${r.status==='متأخر'?`<span class="badge ${r.severity.cls}">${esc(r.severity.label)}</span>`:'—'}</td><td>${r.student?`<button class="btn small gold" onclick="FinancePro.selectStudent('${r.student.id}','payment');FinancePro.render('payment')">تحصيل</button>`:'—'}</td></tr>`);$('#view-installments').innerHTML=`<div class="page-head"><div><h1>متابعة الأقساط</h1><p>الأولوية للأقساط المتأخرة مع انتقال مباشر إلى شاشة التحصيل.</p></div></div><div class="finance-summary-strip" style="margin-bottom:14px"><div class="finance-summary-item"><small>أقساط مفتوحة</small><b>${open.length}</b></div><div class="finance-summary-item"><small>متأخرة</small><b>${overdue.length}</b></div><div class="finance-summary-item"><small>جزئية الدفع</small><b>${partial.length}</b></div></div>${table(['الطالب','الصف','#','الاستحقاق','المستحق','المدفوع','المتبقي','الحالة','درجة التأخر','تحصيل'],rows)}`}
function renderExchange(){const rows=DATA.rates.map(r=>`<tr><td>${esc(r.rate_date)}</td><td>${esc(r.source)}</td><td>${irr(r.rate)}</td><td>${r.is_manual?'يدوي':'آلي'}</td><td>${esc(String(r.fetched_at||'').replace('T',' ').slice(0,19))}</td></tr>`);$('#view-exchange').innerHTML=`<div class="page-head"><div><h1>أسعار الصرف</h1><p>كل دفعة تحفظ سعر الصرف المستخدم وقت العملية.</p></div></div><div class="card"><div class="card-body"><div class="finance-form"><div class="field span-4"><label>سعر USD/IRR يدوي</label><input id="manualRate" class="input" type="number"></div><div class="field span-4"><label>المصدر</label><input id="rateSource" class="input" value="manual"></div><div class="field span-4"><label>&nbsp;</label><button class="btn gold block" onclick="FinancePro.saveRate()">حفظ السعر</button></div></div></div></div>${table(['التاريخ','المصدر','السعر','نوع','وقت الإدخال'],rows)}`}
async function saveRate(){const rate=num($('#manualRate').value);if(!rate){toast('تنبيه','أدخلي السعر','red');return}const {error}=await client().from('exchange_rates').insert({rate,source:$('#rateSource').value||'manual',is_manual:true,created_by:ME.id});if(error)toast('تعذر حفظ سعر الصرف',error.message,'red');else{toast('تم حفظ سعر الصرف','تمت أرشفة السعر المرجعي بنجاح','green');await load()}}
function renderReports(){const classRows=DATA.classes.map(c=>{const fs=DATA.fees.filter(f=>{const s=DATA.studentMap.get(String(f.student_id));return s&&String(s.class_id)===String(c.id)});const due=fs.reduce((a,f)=>a+num(f.net_amount||f.base_amount),0),paid=fs.reduce((a,f)=>a+num(f.total_paid),0);return`<tr><td>${esc(c.name)}</td><td>${fs.length}</td><td>${dualMoney(due)}</td><td>${dualMoney(paid)}</td><td>${dualMoney(due-paid)}</td></tr>`});const overdueRows=DATA.installments.filter(i=>installmentStatus(i)==='متأخر').map(i=>{const f=DATA.fees.find(x=>String(x.id)===String(i.student_fee_id));const s=f&&DATA.studentMap.get(String(f.student_id));return{student:s,studentName:s?fullName(s):'—',className:s?className(s.class_id):'—',due:i.due_date,amount:Math.max(num(i.amount_due)-num(i.amount_paid),0),severity:overdueSeverity(i)}}).sort((a,b)=>b.amount-a.amount);const receiverTotals=Object.values(DATA.payments.reduce((acc,p)=>{const name=receiverName(p);acc[name]=acc[name]||{name,usd:0,count:0};acc[name].usd+=num(p.amount_usd||p.amount);acc[name].count+=1;return acc;},{})).sort((a,b)=>b.usd-a.usd).slice(0,8);$('#view-reports').innerHTML=`<div class="page-head"><div><h1>التقارير المالية</h1><p>تقارير مختصرة تساعدك على القرار بسرعة بدون ازدحام.</p></div></div><div class="finance-summary-strip" style="margin-bottom:14px"><div class="finance-summary-item"><small>عدد الصفوف</small><b>${DATA.classes.length}</b></div><div class="finance-summary-item"><small>أقساط متأخرة</small><b>${overdueRows.length}</b></div><div class="finance-summary-item"><small>مستلمون ظاهرون</small><b>${receiverTotals.length}</b></div></div>${quickLinksBar()}<div class="cards"><div class="card"><div class="card-head"><h3>الإيرادات حسب الصف</h3></div><div class="card-body">${table(['الصف','عدد الملفات','المستحق','المحصّل','المتبقي'],classRows)}</div></div><div class="card"><div class="card-head"><h3>أعلى المتأخرات</h3></div><div class="card-body">${table(['الطالب','الصف','الاستحقاق','المبلغ','الخطورة','تحصيل'],overdueRows.slice(0,12).map(r=>`<tr><td>${esc(r.studentName)}</td><td>${esc(r.className)}</td><td>${esc(r.due?dualDate(r.due):'—')}</td><td>${dualMoney(r.amount)}</td><td><span class="badge ${r.severity.cls}">${esc(r.severity.label)}</span></td><td>${r.student?`<button class="btn small gold" onclick="FinancePro.selectStudent('${r.student.id}','payment');FinancePro.render('payment')">تحصيل</button>`:'—'}</td></tr>`),'لا توجد أقساط متأخرة')}</div></div><div class="card"><div class="card-head"><h3>التحصيل حسب المستلم</h3></div><div class="card-body">${table(['المستلم','عدد العمليات','إجمالي التحصيل'],receiverTotals.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.count}</td><td>${dualMoney(r.usd)}</td></tr>`),'لا توجد عمليات دفع')}</div></div></div>`}
