function auditActionLabel(a){return {INSERT:'إضافة',UPDATE:'تعديل',DELETE:'حذف'}[a]||a}
function auditTableLabel(t){return {student_fees:'ملف مالي',student_installments:'قسط',fee_payments:'دفعة',fee_structures:'رسوم صف',exchange_rates:'سعر صرف',finance_payment_plans:'خطة أقساط'}[t]||t}
function auditSummary(a){const n=a.new_data||{},o=a.old_data||{};if(a.table_name==='fee_payments')return `دفعة ${money(n.amount_usd||n.amount||o.amount)} — إيصال ${n.receipt_number||o.receipt_number||'—'} — المستلم ${n.receiver_name||o.receiver_name||'—'}`;if(a.table_name==='student_fees')return `رسوم الطالب: الصافي ${money(n.net_amount||o.net_amount)} — المدفوع ${money(n.total_paid||o.total_paid)}`;if(a.table_name==='student_installments')return `قسط: المستحق ${money(n.amount_due||o.amount_due)} — المدفوع ${money(n.amount_paid||o.amount_paid)} — الحالة ${n.status||o.status||'—'}`;if(a.table_name==='exchange_rates')return `سعر صرف: ${irr(n.rate||o.rate)} — المصدر ${n.source||o.source||'—'}`;if(a.table_name==='fee_structures')return `رسوم صف: ${money(n.annual_fee||n.amount||o.annual_fee||o.amount)}`;return 'عملية مالية مسجلة'}
function renderAudit(){const rows=DATA.audit.map(a=>`<tr><td>${esc(String(a.gregorian_at||'').replace('T',' ').slice(0,19))}</td><td>${esc(auditTableLabel(a.table_name))}</td><td><span class="badge blue">${esc(auditActionLabel(a.action))}</span></td><td>${esc(auditSummary(a))}</td><td>${esc(a.record_id||'—')}</td></tr>`);$('#view-audit').innerHTML=`<div class="page-head"><div><h1>سجل التدقيق المالي</h1><p>سجل مبسط قابل للقراءة بدلاً من عرض بيانات برمجية خام.</p></div></div>${table(['وقت العملية','القسم','العملية','الملخص','رقم السجل'],rows)}`}
function queueOffline(obj){const q=JSON.parse(localStorage.getItem('finance_offline_queue')||'[]');q.push(Object.assign({id:Date.now(),created_at:new Date().toISOString()},obj));localStorage.setItem('finance_offline_queue',JSON.stringify(q))}function renderOffline(){const q=JSON.parse(localStorage.getItem('finance_offline_queue')||'[]');$('#view-offline').innerHTML=`<div class="page-head"><div><h1>الطوارئ Offline</h1><p>مسودات محفوظة محلياً عند فشل الاتصال. يمكن إدخالها لاحقاً يدوياً.</p></div></div><div class="offline-badge">${q.length} مسودة</div>${table(['الوقت','النوع','البيانات'],q.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.type)}</td><td><pre class="audit-json">${esc(JSON.stringify(x,null,2))}</pre></td></tr>`))}<button class="btn red no-print" onclick="localStorage.removeItem('finance_offline_queue');FinancePro.render('offline')">مسح المسودات</button>`}

function renderExpenses() {
  const list = DATA.expenses || [];
  const totalUsd = list.reduce((a, x) => a + num(x.amount_usd), 0);
  const totalIrr = list.reduce((a, x) => a + num(x.amount_irr), 0);
  const todayCount = list.filter(x => String(x.payment_date).slice(0,10) === iso()).length;

  const rows = list.map(e => {
    const catText = {salaries:'رواتب وأجور', maintenance:'صيانة وتشغيل', utilities:'فواتير خدمات', supplies:'قرطاسية ومستلزمات', activities:'أنشطة وفعاليات', rent:'إيجارات', other:'أخرى'}[e.category] || e.category;
    const methodText = {cash:'نقداً', bank_transfer:'تحويل بنكي', cheque:'شيك', other:'أخرى'}[e.payment_method] || e.payment_method;
    const attBtn = e.attachment_url ? `<a class="btn small blue" href="/api/proxy/storage/v1/object/public/finance-receipts/${e.attachment_url}" target="_blank" style="padding:2px 6px;font-size:11px">عرض السند 📄</a>` : '<span class="muted">—</span>';
    return `<tr><td><b>${esc(e.title)}</b><br><small class="muted">${esc(e.expense_code||'')}</small></td><td><span class="badge gold">${esc(catText)}</span></td><td><b>${dualMoney(e.amount_usd,e.amount_irr)}</b></td><td>${esc(methodText)}</td><td>${esc(e.beneficiary||'—')}</td><td>${esc(dualDate(e.payment_date))}</td><td>${attBtn}</td><td><button class="btn small red" onclick="FinancePro.deleteExpense('${e.id}')">حذف</button></td></tr>`;
  });

  const formHtml = `<div class="card" style="margin-bottom:20px"><div class="card-head"><h3>تسجيل مصروف أو نفقة جديدة</h3></div><div class="card-body"><div class="finance-form">` +
    `<div class="field span-4"><label>عنوان المصروف / البيان *</label><input id="expTitle" class="input" placeholder="مثال: شراء قرطاسية وأقلام للإدارة"></div>` +
    `<div class="field span-4"><label>التصنيف *</label><select id="expCat" class="select"><option value="supplies">قرطاسية ومستلزمات مكتبية</option><option value="utilities">فواتير (كهرباء، ماء، إنترنت)</option><option value="maintenance">صيانة وتشغيل</option><option value="salaries">رواتب وأجور ومكافآت</option><option value="activities">أنشطة ورحلات مدرسية</option><option value="rent">إيجارات ومرافق</option><option value="other">أخرى</option></select></div>` +
    `<div class="field span-4"><label>المستفيد / المورد</label><input id="expBen" class="input" placeholder="مثال: مكتبة النور / شركة الصيانة"></div>` +
    `<div class="field span-3"><label>المبلغ بالدولار ($) *</label><input id="expUsd" type="number" step="0.01" class="input" value="0" oninput="FinancePro.calcExpIrr()"></div>` +
    `<div class="field span-3"><label>سعر الصرف USD/IRR</label><input id="expRate" type="number" class="input" value="${esc((DATA.rates&&DATA.rates[0]) ? DATA.rates[0].rate : 0)}" oninput="FinancePro.calcExpIrr()"></div>` +
    `<div class="field span-3"><label>المبلغ بالريال الإيراني</label><input id="expIrr" type="number" class="input" value="0"></div>` +
    `<div class="field span-3"><label>تاريخ الدفع</label><input id="expDate" type="date" class="input" value="${iso()}"></div>` +
    `<div class="field span-3"><label>طريقة الدفع</label><select id="expMethod" class="select"><option value="cash">نقداً</option><option value="bank_transfer">تحويل بنكي</option><option value="cheque">شيك</option><option value="other">أخرى</option></select></div>` +
    `<div class="field span-3"><label>رقم الفاتورة / السند</label><input id="expReceiptNo" class="input" placeholder="رقم الفاتورة الورقية"></div>` +
    `<div class="field span-6"><label>صورة السند أو الفاتورة 📎</label><div class="upload-box" style="padding:4px;border:1px dashed #ccc;border-radius:6px"><input type="file" id="expPhoto" accept="image/*,application/pdf"><div style="font-size:11px;color:#666">ارفعي صورة الفاتورة (JPG/PNG/PDF)</div></div></div>` +
    `<div class="field span-12"><label>ملاحظات إضافية</label><input id="expNotes" class="input"></div>` +
    `<div class="span-12"><button class="btn gold block" onclick="FinancePro.saveExpense()">حفظ المصروف وإرفاق السند</button></div>` +
    `</div></div></div>`;

  $('#view-expenses').innerHTML = `<div class="page-head"><div><h1>المصروفات والنفقات 💸</h1><p>إدارة النفقات التشغيلية للمدرسة، وتصنيف المصروفات، وإرفاق صور السندات والفواتير.</p></div></div>` +
    `<div class="kpis">${kpi('إجمالي المصروفات', dualMoney(totalUsd,totalIrr), 'red')}${kpi('مصروفات اليوم', todayCount, 'blue')}${kpi('عدد السجلات', list.length, 'green')}${kpi('سعر الصرف', activeRate()?irr(activeRate()):'—', 'gold')}</div>` +
    formHtml + table(['البيان', 'التصنيف', 'المبلغ', 'الطريقة', 'المستفيد', 'التاريخ', 'صورة السند', 'إجراء'], rows, 'لا توجد مصروفات مسجلة');
}

function calcExpIrr() {
  const usd = num($('#expUsd')?.value);
  const rate = num($('#expRate')?.value);
  if ($('#expIrr')) $('#expIrr').value = Math.round(usd * rate);
}

async function saveExpense() {
  const title = $('#expTitle')?.value?.trim();
  if (!title) { toast('تنبيه', 'أدخلي عنوان أو بيان المصروف', 'red'); return; }
  const usd = num($('#expUsd')?.value);
  const irrVal = num($('#expIrr')?.value);
  if (usd <= 0 && irrVal <= 0) { toast('تنبيه', 'أدخلي مبلغاً أكبر من صفر', 'red'); return; }

  const btn = document.querySelector('#view-expenses button[onclick="FinancePro.saveExpense()"]');
  const oldText = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = 'جاري حفظ السند...'; }

  try {
    let attachmentUrl = null;
    const fileEl = $('#expPhoto');
    const file = fileEl && fileEl.files && fileEl.files[0];
    if (file) {
      const ext = (file.name.split('.').pop() || 'jpg').toLowerCase();
      const path = `expenses/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
      const { error } = await client().storage.from('finance-receipts').upload(path, file, { upsert: false, contentType: file.type || 'image/jpeg' });
      if (error) throw error;
      attachmentUrl = path;
    }

    const res = await client().rpc('finance_record_expense', {
      p_title: title,
      p_category: $('#expCat')?.value || 'other',
      p_amount_usd: usd,
      p_amount_irr: irrVal,
      p_exchange_rate: num($('#expRate')?.value) || 0,
      p_payment_method: $('#expMethod')?.value || 'cash',
      p_payment_date: $('#expDate')?.value || iso(),
      p_beneficiary: $('#expBen')?.value || null,
      p_receipt_number: $('#expReceiptNo')?.value || null,
      p_attachment_url: attachmentUrl,
      p_notes: $('#expNotes')?.value || null
    });
    if (res.error) throw res.error;
    const d = res.data || {};
    if (d.ok === false) throw new Error(d.message || 'تعذر الحفظ');

    toast('تم حفظ المصروف', 'تم تسجيل المصروف وحفظ السند بنجاح', 'green');
    await load();
  } catch(e) {
    console.error('saveExpense error:', e);
    toast('تعذر حفظ المصروف', e.message || String(e), 'red');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = oldText; }
  }
}

async function deleteExpense(id) {
  if (!confirm('هل أنت متأكدة من حذف هذا المصروف؟')) return;
  try {
    const res = await client().rpc('finance_delete_expense', { p_expense_id: id });
    if (res.error) throw res.error;
    toast('تم حذف المصروف', 'تم حذف المصروف من السجل بنجاح', 'green');
    await load();
  } catch(e) {
    toast('خطأ في الحذف', e.message || String(e), 'red');
  }
}
